    id:String(value.id || makeId()),
    label:String(value.label || ('Option '+(index+1))),
    directKey:String(value.directKey || ''),
    actionId:String(value.actionId || ''),
    line1:menuDesignerTextForCodes(line1Codes),
    line2:menuDesignerTextForCodes(line2Codes),
    line1Codes:line1Codes,
    line2Codes:line2Codes,
