  if(!Number.isFinite(Number(normalized.keypad.accessCodeTimeoutMs))) normalized.keypad.accessCodeTimeoutMs=30000;
  if(!Number.isFinite(Number(normalized.keypad.userFunctionsTimeoutMs))) normalized.keypad.userFunctionsTimeoutMs=30000;
  if(!Number.isFinite(Number(normalized.keypad.installerMenuTimeoutMs))) normalized.keypad.installerMenuTimeoutMs=1200000;
  if(!Number.isFinite(Number(normalized.keypad.directMenuSelectionDelayMs))) normalized.keypad.directMenuSelectionDelayMs=1100;
  normalized.keypad.directMenuSelectionDelayMs=Math.max(0,Math.min(10000,Math.round(Number(normalized.keypad.directMenuSelectionDelayMs))));
  if(!Number.isFinite(Number(normalized.keypad.labelEntryTimeoutMs))) normalized.keypad.labelEntryTimeoutMs=55000;
  normalized.keypad.labelEntryTimeoutMs=Math.max(0,Math.round(Number(normalized.keypad.labelEntryTimeoutMs)));
