  normalized.keypad.postInstallerSecurityCheckDurationMs=Math.max(0,Math.round(Number(normalized.keypad.postInstallerSecurityCheckDurationMs)));
  if(!Number.isFinite(Number(normalized.keypad.invalidAccessCodeDurationMs))) normalized.keypad.invalidAccessCodeDurationMs=2500;
  if(!Number.isFinite(Number(normalized.keypad.timeDateEntryTimeoutMs))) normalized.keypad.timeDateEntryTimeoutMs=30000;
  normalized.keypad.ledBlinkCycle=hs2lcdNormalizeBlinkCycle(normalized.keypad.ledBlinkCycle,normalized.keypad.ledBlinkOnDurationMs,normalized.keypad.ledBlinkOffDurationMs);
  normalized.keypad.ledBlinkOnDurationMs=normalized.keypad.ledBlinkCycle[0].onDurationMs;
  normalized.keypad.ledBlinkOffDurationMs=normalized.keypad.ledBlinkCycle[0].offDurationMs;
  if(!normalized.audio || typeof normalized.audio!=='object') normalized.audio={};
