  var legacySelectCancel=(normalized.audio.selectCancelTone && typeof normalized.audio.selectCancelTone==='object')?normalized.audio.selectCancelTone:{};
  if(!normalized.audio.selectionTone || typeof normalized.audio.selectionTone!=='object') normalized.audio.selectionTone={};
  if(!normalized.audio.cancelTone || typeof normalized.audio.cancelTone!=='object') normalized.audio.cancelTone={};
  var legacySharedSequence=Array.isArray(legacySelectCancel.sequence)?legacySelectCancel.sequence:null;
