  if(snapshot.screen==='installer-menu') return 'Installer Programming '+(snapshot.installerMenuIndex+1)+' of '+snapshot.installerMenuItemCount+timeoutText+' · '+(snapshot.installerMenuCodeBuffer?'Direct section: '+snapshot.installerMenuCodeBuffer:'Enter a three-digit section, press [*] to select, or use [<][>]')+' · [#] exits programming.';
  if(snapshot.screen==='zone-definitions-menu') return 'Zone Definitions [001] '+(snapshot.zoneDefinitionsMenuIndex+1)+' of '+snapshot.zoneDefinitionsMenuItemCount+timeoutText+' · '+(snapshot.zoneDefinitionsMenuCodeBuffer?'Direct zone: '+snapshot.zoneDefinitionsMenuCodeBuffer:'Enter 001–128, press [*] to select the displayed zone, or use [<][>]')+' · [#] returns to Installer Programming.';
  if(snapshot.screen==='zone-attributes-menu') return 'Zone Attributes [002] '+(snapshot.zoneAttributesMenuIndex+1)+' of '+snapshot.zoneAttributesMenuItemCount+timeoutText+' · '+(snapshot.zoneAttributesMenuCodeBuffer?'Direct zone: '+snapshot.zoneAttributesMenuCodeBuffer:'Enter 001–128, press [*] to select the displayed zone, or use [<][>]')+' · [#] returns to Installer Programming.';
  if(snapshot.screen==='zone-attribute-options-1-8' || snapshot.screen==='zone-attribute-options-9-16') return 'Zone '+snapshot.zoneAttributeZoneNumber+' Attributes '+(snapshot.zoneAttributePage===2?'9–16':'1–8')+' · '+((snapshot.display||{}).line2||'')+timeoutText+' · [<][>] scroll · [*] toggles Y/N · [1]–[8] jump and toggle · [9] switches attribute pages · [#] saves and returns to the same zone.';
  if(snapshot.screen==='system-times-menu') return 'System Times [005] '+(snapshot.systemTimesMenuIndex+1)+' of '+snapshot.systemTimesMenuItemCount+timeoutText+' · '+(snapshot.systemTimesMenuCodeBuffer?'Direct subsection: '+snapshot.systemTimesMenuCodeBuffer:'Enter 000–008 or 900–902, press [*] to select, or use [<][>]')+' · [#] returns to Installer Programming.';
  if(snapshot.screen==='system-time-sequential-editor') return 'System Times sequential entry · '+((snapshot.display||{}).line1||'')+' · digit '+(Number(snapshot.systemTimeDigitCursor)+1)+' of 3'+timeoutText+' · numeric entry replaces the underlined digit · [<] stops at digit 1 · [>] advances and confirms from digit 3 · [#] returns without saving the current unconfirmed field.';
  if(snapshot.screen==='system-time-sequential-confirmed') return 'System Times value '+snapshot.systemTimeWorkingValue+' confirmed · no underline for 1.10 seconds, then the next sequential field opens.';
