  navigationDesignerCatalog(config).forEach(function(def){if(def.kind==='ascii')return;var items=JSON.parse(JSON.stringify(config[def.key]||[]));var changed=false;items.forEach(function(item){fields.forEach(function(field){if(String((item||{})[field]||'')===oldId){item[field]=newId;changed=true;}});});if(changed)state.panelSimulator.updateConfiguration(def.key,items);});
