function applyVirtualKeypadBlinkCycle(cycle){
  if(!state.panelSimulator) return;
  var normalized=hs2lcdNormalizeBlinkCycle(cycle,230,160);
  state.panelSimulator.updateConfiguration('keypad.ledBlinkCycle',normalized);
  persistNeoSimulator();
  state.virtualKeypadBlinkPhase=true;
  state.virtualKeypadBlinkStepIndex=0;
  updateVirtualKeypadIndicatorLights();
  restartVirtualKeypadBlinkTimer();
}
function runVirtualKeypadBlinkCycleAction(action,index){
  var config=simulatorConfig() || {};
  var cycle=virtualKeypadBlinkCycleFromConfig(config.keypad || {});
  index=Math.round(Number(index));
  if(action==='add'){
    var template=cycle.length?cycle[cycle.length-1]:{onDurationMs:230,offDurationMs:160};
    cycle.push({onDurationMs:template.onDurationMs,offDurationMs:template.offDurationMs});
  }else if(action==='delete'){
    if(cycle.length<=1 || index<0 || index>=cycle.length) return;
    cycle.splice(index,1);
  }else if(action==='up'){
    if(index<=0 || index>=cycle.length) return;
    var prior=cycle[index-1];cycle[index-1]=cycle[index];cycle[index]=prior;
  }else if(action==='down'){
    if(index<0 || index>=cycle.length-1) return;
    var next=cycle[index+1];cycle[index+1]=cycle[index];cycle[index]=next;
  }else return;
  applyVirtualKeypadBlinkCycle(cycle);
  renderNeoSimulatorConfig();
}
function workspaceDetailsOwnStateToken(detail){
  if(!detail) return '';
  var attrs=['data-config-card-key','data-collapse-key','data-nav-system-screen','data-nav-option-index','data-nav-boot-index','data-menu-card-key','id'];
  for(var i=0;i<attrs.length;i++){
    var value=detail.getAttribute&&detail.getAttribute(attrs[i]);
    if(value) return attrs[i]+'='+String(value);
  }
  var stableClasses=String(detail.className||'').split(/\s+/).filter(function(name){
    return name && !/^(open|active|is-|collapsed|subcollapsed)/.test(name);
  }).slice(0,3);
  var summary=detail.querySelector&&detail.querySelector(':scope > summary');
  var text=summary?String(summary.textContent||'').replace(/\s+/g,' ').trim():'';
  return (stableClasses.length?'class='+stableClasses.join('.'):'details')+'|summary='+text;
}
function workspaceNearestParentDetails(detail,root){
  var parent=detail&&detail.parentElement;
  while(parent&&parent!==root){if(String(parent.tagName||'').toLowerCase()==='details')return parent;parent=parent.parentElement;}
  return null;
}
function workspaceDetailsStateKey(detail,root){
  if(!detail) return '';
  var parts=[],cursor=detail,guard=0;
  while(cursor&&cursor!==root&&guard++<20){
    var own=workspaceDetailsOwnStateToken(cursor);
    var parent=workspaceNearestParentDetails(cursor,root);
    var scope=parent||root;
    var ordinal=0;
    if(scope&&scope.querySelectorAll){
      var peers=Array.prototype.slice.call(scope.querySelectorAll('details')).filter(function(candidate){return workspaceNearestParentDetails(candidate,scope)===null;});
      var index=peers.indexOf(cursor);if(index>=0)ordinal=index;
    }
    parts.unshift(own+'#'+ordinal);
    cursor=parent;
  }
  return parts.join('>');
}
function workspaceCaptureDetailsState(root){
  var states={};if(!root)return states;
  qsa('details',root).forEach(function(detail){var key=workspaceDetailsStateKey(detail,root);if(key)states[key]=!!detail.open;});
  if(String(root.tagName||'').toLowerCase()==='details'){
    var rootKey='__root__:'+workspaceDetailsOwnStateToken(root);states[rootKey]=!!root.open;
  }
  return states;
}
function workspaceRestoreDetailsState(root,states){
  if(!root||!states||typeof states!=='object')return;
  if(String(root.tagName||'').toLowerCase()==='details'){
    var rootKey='__root__:'+workspaceDetailsOwnStateToken(root);if(Object.prototype.hasOwnProperty.call(states,rootKey))root.open=!!states[rootKey];
  }
  qsa('details',root).forEach(function(detail){var key=workspaceDetailsStateKey(detail,root);if(key&&Object.prototype.hasOwnProperty.call(states,key))detail.open=!!states[key];});
}
function neoSimulatorConfigOpenSectionTitles(mount){
  if(!mount) return [];
  return qsa('details[open]',mount).map(function(section){
    var key=section.getAttribute('data-config-card-key');
    if(key) return 'key:'+key;
    var summary=section.querySelector(':scope > summary') || section.querySelector('summary');
    return summary ? 'summary:'+summary.textContent.trim() : '';
  }).filter(Boolean);
}
function restoreNeoSimulatorConfigOpenSections(mount,titles){
  if(!mount || !Array.isArray(titles) || !titles.length) return;
  var wanted={};
  titles.forEach(function(title){wanted[title]=true;});
  qsa('details',mount).forEach(function(section){
    var key=section.getAttribute('data-config-card-key');
    var summary=section.querySelector(':scope > summary') || section.querySelector('summary');
    var token=key ? 'key:'+key : (summary ? 'summary:'+summary.textContent.trim() : '');
    if(token && wanted[token]) section.open=true;
  });
}
