  var toggles='<div class="simulator-zone-attribute-grid">';for(var p=1;p<=8;p++){var on=!!values[String(p)];toggles+='<label class="simulator-zone-attribute-toggle '+(on?'is-enabled':'')+'"><input data-sim-config="'+base+p+'" type="checkbox" '+(on?'checked':'')+'><span><strong>Partition '+p+'</strong><small>'+(on?'Y':'N')+'</small></span></label>';}toggles+='</div>';
  return '<div class="simulator-config-body"><p class="muted simulator-boundary-note simulator-config-intro">These are the saved Section [007] values used by the virtual keypad. Select Bell or any PGM 1–164, then edit all eight partition assignments.</p><div class="simulator-form-grid"><label>Output to configure<select data-sim-config-view="pgm-partition-target">'+options+'</select><small>Choose the Bell output or any PGM 1–164.</small></label></div>'+toggles+'</div>';
