    if(String(item.id||'')==='contrast-control'||code==='13')return 'Open Contrast control';
    if(String(item.id||'')==='buzzer-control'||code==='14')return 'Open Buzzer control';
    if(String(item.id||'')==='exit')return 'Back one level';
