  var meta=def.meta?((config||{})[def.meta]||{}):{};
  var previewMs=meta.directEntrySelectionDelayMs==null?(((config||{}).keypad||{}).directMenuSelectionDelayMs==null?1100:Number(((config||{}).keypad||{}).directMenuSelectionDelayMs)):Number(meta.directEntrySelectionDelayMs);
  var progressive=meta.directEntryProgressiveDisplay!==false;
  var placeholder=String(meta.directEntryPlaceholder==null?'-':meta.directEntryPlaceholder).slice(0,1)||'-';
  var metaPath=def.meta||'';
  var example=codes[0]||new Array(digits+1).join('0');
  var first=String(example).charAt(0)+(new Array(digits).join(placeholder));
  var second=digits>1?String(example).slice(0,2)+(new Array(Math.max(1,digits-1)).join(placeholder)):String(example);
