function navigationDesignerCaptureScrollState(mount){
  if(!mount) return null;
  var snapshot={windowX:window.pageXOffset||document.documentElement.scrollLeft||document.body.scrollLeft||0,windowY:window.pageYOffset||document.documentElement.scrollTop||document.body.scrollTop||0,ancestors:[],descendants:{}};
  var node=mount.parentElement;
  while(node&&node!==document.body&&node!==document.documentElement){
    var style=window.getComputedStyle?window.getComputedStyle(node):null;
    var canY=node.scrollHeight>node.clientHeight+1&&(!style||/(auto|scroll|overlay)/.test(style.overflowY||style.overflow));
    var canX=node.scrollWidth>node.clientWidth+1&&(!style||/(auto|scroll|overlay)/.test(style.overflowX||style.overflow));
    if(canY||canX)snapshot.ancestors.push({node:node,top:node.scrollTop,left:node.scrollLeft});
    node=node.parentElement;
  }
  [['optionTable','.navigation-designer-option-table'],['treeScroll','.nav-tree-scroll'],['optionEditors','.navigation-option-editor-cards']].forEach(function(pair){var el=mount.querySelector(pair[1]);if(el)snapshot.descendants[pair[0]]={top:el.scrollTop,left:el.scrollLeft};});
  return snapshot;
}
function navigationDesignerRestoreScrollState(snapshot,mount){
  if(!snapshot) return;
  function apply(){
    snapshot.ancestors.forEach(function(entry){if(entry.node&&entry.node.isConnected){entry.node.scrollTop=entry.top;entry.node.scrollLeft=entry.left;}});
    if(mount&&mount.isConnected){var map={optionTable:'.navigation-designer-option-table',treeScroll:'.nav-tree-scroll',optionEditors:'.navigation-option-editor-cards'};Object.keys(snapshot.descendants||{}).forEach(function(key){var el=mount.querySelector(map[key]||'');var saved=snapshot.descendants[key];if(el&&saved){el.scrollTop=saved.top;el.scrollLeft=saved.left;}});}
    try{var root=document.documentElement;var priorBehavior=root.style.scrollBehavior;root.style.scrollBehavior='auto';window.scrollTo(snapshot.windowX,snapshot.windowY);root.style.scrollBehavior=priorBehavior;}catch(error){}
  }
  apply();
  requestAnimationFrame(function(){apply();requestAnimationFrame(apply);});
  setTimeout(apply,80);
}

