    if(runId!==state.lcdTransitionRunId) return;
    state.lcdTransitionTimer=null;
    renderHS2LCDFrame(line1,line2,options);
    state.lcdDisplayedTextSignature=transitionSignature;
    if(fadeInDuration<=0){
      canvas.style.transition='none';
      canvas.style.opacity='';
      return;
    }
