    var key=lamp.getAttribute('data-status-lamp');
    var resolved=indicatorResolver(key) || {state:'off',active:false};
    lamp.classList.toggle('active',!!resolved.active);
    lamp.classList.toggle('blinking',resolved.state==='blink');
    var label=(key==='ac'?'AC':key.charAt(0).toUpperCase()+key.slice(1))+' indicator ';
    label+=resolved.state==='blink'?'blinking ('+(resolved.active?'lit':'dark')+')':(resolved.active?'on':'off');
