  if(!context) return null;
  if(context.state==='suspended' && context.resume) context.resume();
  var frequency=hs2lcdClampNumber(spec.frequencyHz,100,12000,2615);
  var durationMs=hs2lcdClampNumber(spec.durationMs,10,10000,90);
  var volume=hs2lcdClampNumber(spec.volume,0,1,0.08);
  if(volume<=0 || frequency<=0) return null;
  var attackMs=hs2lcdClampNumber(spec.attackMs,0,500,4);
  var releaseMs=hs2lcdClampNumber(spec.releaseMs,0,2000,14);
  var waveform=hs2lcdNormalizeWaveform(spec.waveform,'sine');
