  var end=start+(durationMs/1000);
  var attackEnd=Math.min(end,start+(attackMs/1000));
  var releaseStart=Math.max(attackEnd,end-(releaseMs/1000));
  var output=context.createGain();
  output.gain.setValueAtTime(0.0001,start);
  output.gain.linearRampToValueAtTime(volume,attackEnd);
  output.gain.setValueAtTime(volume,releaseStart);
  output.gain.exponentialRampToValueAtTime(0.0001,end);
  output.connect(context.destination);

  var oscillator=context.createOscillator();
  oscillator.type=waveform;
  oscillator.frequency.setValueAtTime(frequency,start);
  oscillator.connect(output);
  oscillator.start(start);
  oscillator.stop(end+0.02);
  hs2lcdTrackAudioNode(oscillator);

