    harmonicOutput.gain.setValueAtTime(0.0001,start);
    harmonicOutput.gain.linearRampToValueAtTime(volume*harmonicGain,attackEnd);
    harmonicOutput.gain.setValueAtTime(volume*harmonicGain,releaseStart);
    harmonicOutput.gain.exponentialRampToValueAtTime(0.0001,end);
