function referenceRecordById(referenceId){
  var referenceAliases={
    'neo-zone-attributes-table-v2':'neo-zone-attributes-table',
    'new-powerseries-zone-attributes-table-v2':'new-powerseries-zone-attributes-table',
    'neo-default-zone-attributes-per-zone-type-table-v2':'neo-default-zone-attributes-per-zone-type-table',
    'new-powerseries-default-zone-attributes-per-zone-type-table-v2':'new-powerseries-default-zone-attributes-per-zone-type-table'
  };
  referenceId=referenceAliases[referenceId]||referenceId;
  var records=[
    NEO_REFERENCE_DATA.zoneTypes,
    NEO_REFERENCE_DATA.wirelessTools,
    NEO_REFERENCE_DATA.zoneTypesTable,
    NEO_REFERENCE_DATA.zoneAttributesTable,
    NEO_REFERENCE_DATA.defaultZoneAttributesPerZoneTypeTable,
    NEO_REFERENCE_DATA.systemEventsTable,
    NEO_REFERENCE_DATA.systemEventSummary,
    NEO_REFERENCE_DATA.keypadTextEntry,
    NEO_REFERENCE_DATA.keypadWordLibrary,
    NEO_REFERENCE_DATA.reportingCodes,
    NEO_REFERENCE_DATA.panelSpecifications,
    NEO_REFERENCE_DATA.panelInstallation,
    POWERSERIES_REFERENCE_DATA.zoneTypes,
    POWERSERIES_REFERENCE_DATA.zoneTypesTable,
    POWERSERIES_REFERENCE_DATA.zoneAttributesTable,
    POWERSERIES_REFERENCE_DATA.defaultZoneAttributesPerZoneTypeTable,
    POWERSERIES_REFERENCE_DATA.systemEventsTable,
    POWERSERIES_REFERENCE_DATA.systemEventSummary,
    POWERSERIES_REFERENCE_DATA.reportingCodes,
    POWERSERIES_REFERENCE_DATA.reportingCodesV2
  ];
  for(var i=0;i<records.length;i++) if(records[i] && records[i].id===referenceId) return records[i];
  return null;
}
function zoneTypeFamilyKey(item){
  return String(item&&item.familyKey||'neo');
}
function zoneTypeContactCategory(item){
  var rule=String(item&&item.sensorRuleType||'');
  var text=lower(item&&item.sensorCompatibility||'');
  if(rule==='wireless-addressable-only') return 'wireless';
  if(text.indexOf('wireless')>=0) return 'wireless';
  if(text.indexOf('no sensor (unused')>=0 || rule==='future-use') return 'unused';
  if(text.indexOf('nc or no')>=0) return 'both';
  if(text.indexOf('no sensor only')>=0 || text.indexOf('normally open only')>=0) return 'no';
  if(text.indexOf('nc sensor only')>=0 || text.indexOf('normally closed only')>=0) return 'nc';
  return 'other';
}
function zoneTypeSupervisionCategory(item){
  var rule=String(item&&item.sensorRuleType||'');
  if(rule==='fixed-no'||rule==='fixed-seol') return 'fixed';
  if(rule==='section-013') return 'configurable';
  if(rule==='wireless-only'||rule==='wireless-addressable-only') return 'wireless';
  if(rule==='unused'||rule==='future-use') return 'unused';
  return 'other';
}
function zoneTypeContactBadge(item){
  var category=zoneTypeContactCategory(item), rule=String(item&&item.sensorRuleType||'');
  if(rule==='wireless-addressable-only') return 'Wireless/addressable only';
  if(category==='both') return 'NC + NO';
  if(category==='nc') return 'NC only';
  if(category==='no') return 'NO only';
  if(category==='wireless') return 'Wireless only';
  if(category==='unused') return rule==='future-use'?'Not defined':'No sensor';
  return item&&item.sensorCompatibility||'Other';
}
function zoneTypeSupervisionBadge(item){
  var category=zoneTypeSupervisionCategory(item), family=zoneTypeFamilyKey(item), rule=String(item&&item.sensorRuleType||'');
  if(rule==='fixed-seol') return 'Fixed SEOL';
  if(category==='fixed') return 'Fixed supervision';
  if(category==='configurable') return family==='ps462'?'Follows [013] / A14-16 (Z1-8)':'Follows [013] / [002] override';
  if(rule==='wireless-addressable-only') return 'EOL N/A';
  if(category==='wireless') return 'EOL N/A';
  if(category==='unused') return rule==='future-use'?'Future Use':'Unused · EOL N/A';
  return 'Other';
}
function zoneTypeProgrammingName(item){
  return String(item&&item.programmingName||item&&item.label||'Zone Type');
}
function zoneTypeKeypadName(item){
  return String(item&&item.keypadName||item&&item.label||zoneTypeProgrammingName(item));
}
function zoneTypeIs24Hour(item){
  if(item&&typeof item.is24HourDefinition==='boolean') return item.is24HourDefinition;
  return /(?:^|\b)24\s*(?:-|\s)?\s*(?:hr|hour)\b/i.test(zoneTypeProgrammingName(item)+' '+zoneTypeKeypadName(item));
}
function zoneTypeAlarmType(item){
  var value=item&&item.alarmType;
  if(value===undefined||value===null||String(value).trim()==='') return 'Unspecified';
  return String(value);
}
function zoneTypeAlarmDisplayLabel(value){
  value=String(value===undefined||value===null?'':value).trim();
  return value==='-'||value===''||value==='Unspecified'?'No Category':value;
}
function zoneTypeTroubleType(item){
  var value=item&&item.troubleType;
  return value===undefined||value===null||String(value).trim()===''?'—':String(value);
}
function zoneTypeAlarmThemeKeyFromValue(value){
  var key=lower(String(value===undefined||value===null?'':value)).trim();
  if(key==='burglary') return 'burglary';
  if(key==='fire') return 'fire';
  if(key==='supervisory') return 'supervisory';
  if(key==='fire supervisory') return 'fire-supervisory';
  if(key==='priority') return 'priority';
  if(key==='carbon monoxide') return 'carbon-monoxide';
  if(key==='holdup') return 'holdup';
  if(key==='panic') return 'panic';
  if(key==='medical') return 'medical';
  if(key==='emergency') return 'emergency';
  if(key==='other') return 'other';
  if(key==='no alarm') return 'no-alarm';
  return 'neutral';
}
function zoneTypeAlarmThemeKey(item){
  return zoneTypeAlarmThemeKeyFromValue(zoneTypeAlarmType(item));
}
function zoneTypeAlarmSwatch(themeKey){
  return '<span class="zone-type-alarm-swatch zone-type-alarm-swatch-'+esc(themeKey||'neutral')+'" aria-hidden="true"></span>';
}
