function zoneTypeWiringSvg(kind){
  /* v805: rebalanced the diagram layout for clearer label placement and fuller use of the canvas. */
  var common='viewBox="0 0 420 210" role="img" aria-hidden="true" focusable="false"';
  var terminals='<g class="zone-wire-terminal"><rect x="14" y="36" width="62" height="38" rx="8"></rect><text x="45" y="60" text-anchor="middle">Z</text><rect x="14" y="144" width="62" height="38" rx="8"></rect><text x="45" y="168" text-anchor="middle">COM</text></g>';
  var topStart='<path d="M76 55H138"></path>';
  var topToSensor='<path d="M138 55H302"></path>';
  var bottom='<path d="M76 163H302V138"></path>';
  var sensorTop='<path d="M302 55V94"></path>';
  var sensorNodes='<circle cx="302" cy="94" r="4.5"></circle><circle cx="302" cy="138" r="4.5"></circle>';
  var nc='<g class="zone-wire-contact">'+sensorNodes+'<line x1="302" y1="98" x2="302" y2="134"></line><text class="zone-wire-diagram-label" x="321" y="120">NC</text></g>';
  var no='<g class="zone-wire-contact">'+sensorNodes+'<line x1="302" y1="134" x2="274" y2="103"></line><text class="zone-wire-diagram-label" x="321" y="120">NO</text></g>';
  var sensorLabel='<text class="zone-wire-diagram-label" x="254" y="116" text-anchor="middle">SENSOR</text>';
  var loopLabel='<text class="zone-wire-diagram-label zone-wire-muted-label" x="118" y="40" text-anchor="middle">ZONE LOOP</text>';
  var series='<g class="zone-wire-resistor"><path d="M170 55h8l6-11 10 22 10-22 10 22 10-22 6 11h8"></path><text class="zone-wire-value-label" x="206" y="85" text-anchor="middle">5.6kΩ</text></g>';
  var parallelBranches='<path d="M302 94H356"></path><path d="M302 138H356"></path>';
  var parallel='<g class="zone-wire-resistor zone-wire-resistor-parallel"><path d="M356 94v8l-8 5 16 6-16 6 16 6-16 6 16 6-8 5v0"></path><text class="zone-wire-value-label" x="389" y="121" text-anchor="middle">5.6kΩ</text></g>';
  var parallelLabel='<text class="zone-wire-diagram-label zone-wire-muted-label" x="359" y="81" text-anchor="middle">PARALLEL EOL</text>';
  if(kind==='nc-none') return '<svg '+common+'>'+terminals+'<g class="zone-wire-lines">'+topStart+topToSensor+sensorTop+bottom+'</g>'+loopLabel+sensorLabel+nc+'</svg>';
  if(kind==='nc-seol') return '<svg '+common+'>'+terminals+'<g class="zone-wire-lines">'+topStart+'<path d="M138 55H170"></path><path d="M242 55H302"></path>'+sensorTop+bottom+'</g>'+series+loopLabel+sensorLabel+nc+'</svg>';
  if(kind==='no-seol') return '<svg '+common+'>'+terminals+'<g class="zone-wire-lines">'+topStart+topToSensor+sensorTop+bottom+parallelBranches+'</g>'+loopLabel+sensorLabel+parallelLabel+no+parallel+'</svg>';
  if(kind==='nc-deol') return '<svg '+common+'>'+terminals+'<g class="zone-wire-lines">'+topStart+'<path d="M138 55H170"></path><path d="M242 55H302"></path>'+sensorTop+bottom+parallelBranches+'</g>'+series+loopLabel+sensorLabel+parallelLabel+nc+parallel+'</svg>';
  return '';
}
