/* v441 table heading compatibility markers: <th>Programming name</th><th>Keypad name</th><th>Description</th><th>Alarm type</th><th>Trouble type</th><th>24 Hour</th><th>Sensor contact</th><th>Supervision</th><th>Characteristics</th><th>EOL behavior</th><th>Wiring</th><th>Notes</th><th>Arming behavior</th> */
/* v803: Search only each zone type's own visible details. Recursing over raw
   reference objects can introduce cross-record / non-displayed terminology. */
function renderZoneTypesTable(entries){
  var columns=zoneTypesTableColumns();
  var html='<div class="zone-types-table-wrap" data-zone-types-table-wrap hidden><div class="table-scroll zone-types-table-scroll"><table class="reference-table zone-types-table" data-zone-types-table><thead><tr>'+columns.map(function(column){return '<th data-zone-types-column="'+esc(column.key)+'">'+esc(column.label)+'</th>';}).join('')+'</tr></thead><tbody>';
  entries.forEach(function(item){
    var contact=zoneTypeContactCategory(item), supervision=zoneTypeSupervisionCategory(item), alarmType=zoneTypeAlarmType(item), troubleType=zoneTypeTroubleType(item), is24=zoneTypeIs24Hour(item), characteristics=zoneTypeCharacteristicTags(item);
    var programmingName=zoneTypeProgrammingName(item), keypadName=zoneTypeKeypadName(item), themeKey=zoneTypeAlarmThemeKeyFromValue(alarmType);
    var primarySearch=lower([item.code,programmingName,keypadName,alarmType].join(' '));
    var nameSearch=lower([programmingName,keypadName].join(' '));
    var armingText=(item.armingMethods||[]).map(function(row){return (row||[]).join(' · ');}).join('\n');
    var informationSearch=lower([item.description,item.sensorCompatibility,zoneTypeContactBadge(item),zoneTypeSupervisionBadge(item),alarmType,item.troubleType,is24?'24 hour definition':'',characteristics.join(' '),(item.resistorWiring||''),(item.eolBehavior||''),(item.notes||[]).join(' '),armingText,zoneTypeDefaultAttributeSearchText(item)].join(' '));
    html+='<tr data-zone-type-table-row data-zone-type-code="'+esc(item.code||'')+'" data-zone-type-search-name="'+esc(nameSearch)+'" data-zone-type-contact="'+esc(contact)+'" data-zone-type-supervision="'+esc(supervision)+'" data-zone-type-24-hour="'+(is24?'yes':'no')+'" data-zone-type-alarm-type="'+esc(alarmType)+'" data-zone-type-alarm-theme="'+esc(themeKey)+'" data-zone-type-trouble-type="'+esc(troubleType)+'" data-zone-type-characteristics="'+esc(characteristics.join('|'))+'" data-zone-type-search-primary="'+esc(primarySearch)+'" data-zone-type-search-information="'+esc(informationSearch)+'">';
    html+='<td data-zone-types-column="code" class="zone-types-table-code">'+esc(item.code||'---')+'</td>';
    html+='<td data-zone-types-column="programming"><strong>'+esc(programmingName)+'</strong></td>';
    html+='<td data-zone-types-column="keypad">'+esc(keypadName)+'</td>';
    html+='<td data-zone-types-column="description" class="zone-types-table-description">'+esc(item.description||'—')+'</td>';
    html+='<td data-zone-types-column="alarm"><span class="zone-types-table-alarm">'+zoneTypeAlarmSwatch(themeKey)+'<span>'+esc(zoneTypeAlarmDisplayLabel(alarmType))+'</span></span></td>';
    html+='<td data-zone-types-column="trouble">'+esc(troubleType)+'</td>';
    html+='<td data-zone-types-column="twentyFour">'+(is24?'Yes':'No')+'</td>';
    html+='<td data-zone-types-column="contact">'+esc(zoneTypeContactBadge(item))+'</td>';
    html+='<td data-zone-types-column="supervision">'+esc(zoneTypeSupervisionBadge(item))+'</td>';
    html+='<td data-zone-types-column="characteristics">'+esc(characteristics.length?characteristics.join(' · '):'—')+'</td>';
    html+='<td data-zone-types-column="eol" class="zone-types-table-multiline">'+esc(item.eolBehavior||'—').replace(/\n/g,'<br>')+'</td>';
    html+='<td data-zone-types-column="wiring" class="zone-types-table-multiline">'+esc(item.resistorWiring||'—').replace(/\n/g,'<br>')+'</td>';
    html+='<td data-zone-types-column="notes" class="zone-types-table-multiline">'+esc((item.notes||[]).join('\n')||'—').replace(/\n/g,'<br>')+'</td>';
    html+='<td data-zone-types-column="arming" class="zone-types-table-multiline">'+esc(armingText||'—').replace(/\n/g,'<br>')+'</td>';
    html+='</tr>';
  });
  return html+'</tbody></table></div></div>';
}
