  function buildGroupedZoneTypes(){
    if(!listHost||!groupCategories.length) return;
    restoreUngroupedZoneTypes();
    groupCategories.forEach(function(groupKind,categoryIndex){
      var grouped={};
      items.forEach(function(item){
        var valuesForItem=zoneTypeGroupValuesForItem(item,groupKind);
        valuesForItem.forEach(function(value,valueIndex){
          if(!grouped[value]) grouped[value]=[];
          if(categoryIndex===0&&valueIndex===0) grouped[value].push(item);
          else {var clone=item.cloneNode(true);clone.setAttribute('data-zone-type-clone','');grouped[value].push(clone);}
        });
      });
      var values=Object.keys(grouped).sort(function(a,b){var ai=zoneTypeGroupSortIndex(groupKind,a),bi=zoneTypeGroupSortIndex(groupKind,b);return ai===bi?zoneTypeGroupLabel(groupKind,a).localeCompare(zoneTypeGroupLabel(groupKind,b)):ai-bi;});
      var container=document.createElement('details');
      container.className='zone-types-filter-group-container';
      container.setAttribute('data-zone-types-group-container',groupKind);
      container.setAttribute('data-zone-types-group-kind',groupKind);
      container.open=zoneGroupSectionOpenState[groupKind]!==false;
      container.innerHTML='<summary class="zone-types-filter-group-container-head"><span class="zone-types-filter-group-container-title"><span class="zone-types-filter-group-container-chevron" aria-hidden="true"></span><strong>'+esc(filterFieldLabel(groupKind))+'</strong><small data-zone-types-group-container-count>'+values.length+' group'+(values.length===1?'':'s')+'</small></span><span class="zone-types-filter-group-container-actions" aria-label="Expand and collapse '+esc(filterFieldLabel(groupKind))+' groups"><button type="button" class="secondary compact-action-button compact-icon-action" data-zone-types-group-section-action="expand" aria-label="Expand all '+esc(filterFieldLabel(groupKind))+' groups" title="Expand all '+esc(filterFieldLabel(groupKind))+' groups"><span aria-hidden="true">＋</span></button><button type="button" class="secondary compact-action-button compact-icon-action" data-zone-types-group-section-action="collapse" aria-label="Collapse all '+esc(filterFieldLabel(groupKind))+' groups" title="Collapse all '+esc(filterFieldLabel(groupKind))+' groups"><span aria-hidden="true">−</span></button></span></summary><div class="zone-types-filter-group-list" data-zone-types-filter-group-list></div>';
      var groupList=container.querySelector('[data-zone-types-filter-group-list]');
      values.forEach(function(value){
        var themeKey=groupKind==='alarmType'?zoneTypeAlarmThemeKeyFromValue(value):'neutral',group=document.createElement('details'),stateKey=zoneTypeGroupStateKey(groupKind,value);
        group.className='zone-types-alarm-group zone-types-category-value-group program-style-category';
        group.id='zone-types-group-'+encodeURIComponent(groupKind)+'-'+encodeURIComponent(value);
        group.setAttribute('data-zone-types-alarm-group',value);
        group.setAttribute('data-zone-types-group-kind',groupKind);
        group.setAttribute('data-zone-type-alarm-theme',themeKey);
        group.open=zoneGroupOpenState[stateKey]===true;
        var summary=document.createElement('summary');
        summary.className='zone-types-alarm-group-summary';
        var groupSwatch=groupKind==='alarmType'?zoneTypeAlarmSwatch(themeKey):'<span class="zone-type-group-neutral-swatch" aria-hidden="true"></span>';
        summary.innerHTML='<span class="zone-types-alarm-group-title">'+groupSwatch+'<strong data-zone-types-alarm-group-label data-zone-types-group-label>'+esc(zoneTypeGroupLabel(groupKind,value))+'</strong><span class="zone-types-alarm-group-result-dot" data-zone-types-alarm-group-result-dot hidden aria-hidden="true"></span></span><span class="zone-types-alarm-group-meta"><span data-zone-types-alarm-group-count>'+grouped[value].length+' zone type'+(grouped[value].length===1?'':'s')+'</span></span>';
        var grid=document.createElement('div');
        grid.className='zone-types-alarm-group-grid';
        grouped[value].sort(function(a,b){return Number(a.getAttribute('data-zone-type-code'))-Number(b.getAttribute('data-zone-type-code'));}).forEach(function(item){grid.appendChild(item);});
        group.appendChild(summary);group.appendChild(grid);groupList.appendChild(group);
        group.addEventListener('toggle',function(){zoneGroupOpenState[stateKey]=group.open;});
      });
      container.addEventListener('toggle',function(){zoneGroupSectionOpenState[groupKind]=container.open;persistZoneGroupSectionOpenState();if(viewMode==='list')scheduleZoneTypesPackedLayout(listHost);});
      listHost.appendChild(container);
    });
    listHost.classList.add('zone-types-alarm-grouped','zone-types-filter-category-grouped');
    listHost.style.setProperty('--document-column-count',String(listColumns));
    listHost.style.setProperty('--zone-types-group-columns',String(groupColumns));
    syncZoneGroupVisibility();
  }
