  filters.batteryType=previousBatteryTypes.reduce(function(list,value){
    String(value||'').split(/\s*,\s*/).forEach(function(model){
      model=model.trim();if(model&&list.indexOf(model)<0)list.push(model);
    });
    return list;
  },[]);
  if(previousBatteryTypes.join('||')!==filters.batteryType.join('||'))save('dsc-wireless-tools-filters-v1',filters);

  var activeField=String(read('dsc-wireless-tools-filter-field-v1','all')||'all');
  var activeSubfields={battery:'batteryType',compatibility:'panelRegular'};
