  var showFilters=read('dsc-wireless-tools-show-filters-v1',true)!==false, showColumns=read('dsc-wireless-tools-show-columns-v1',false)===true;
  var viewMode=read('dsc-wireless-tools-view-mode-v1','list')==='table'?'table':'list';
  var listColumns=Math.max(1,Math.min(4,Number(read('dsc-wireless-tools-list-columns-v1',1))||1));
  var groupColumns=Math.max(1,Math.min(4,Number(read('dsc-wireless-tools-group-columns-v2',1))||1));
