    if(!tokens.some(function(token){return normalized.indexOf(token)>=0;})) return;
    pattern.lastIndex=0;
    var fragment=document.createDocumentFragment(),last=0,match;
    while((match=pattern.exec(original))){
      fragment.appendChild(document.createTextNode(original.slice(last,match.index)));
      var mark=document.createElement('mark');
      mark.className='programming-search-hit';
      mark.textContent=match[0];
      programmingLocalSearchMarks.push(mark);
      fragment.appendChild(mark);
      last=match.index+match[0].length;
      if(match.index===pattern.lastIndex)pattern.lastIndex++;
    }
    fragment.appendChild(document.createTextNode(original.slice(last)));
    if(node.parentNode)node.parentNode.replaceChild(fragment,node);
