  if(clearButton)clearButton.addEventListener('click',function(){if(programmingLocalSearchTimer){window.clearTimeout(programmingLocalSearchTimer);programmingLocalSearchTimer=0;}input.value='';programmingLocalSearchCommitted='';applyProgrammingLocalSearch({expand:false,collapseOnClear:true});input.focus();});
