/* v688 — Any non-sequential/non-toggle entry in Programming v4.62 New
   uses the same header badge language as the custom entry/sequential/toggle
   renderers. This applies to leaf entries and entry containers such as [005]. */
function isPs462EntryTypedNode(node){
  if(!isNewPowerSeries462Programming() || !isCompactProgrammingPresentation() || !node) return false;
  var type=String(node.entryType||node.type||getProgramTypeText(node)||'').toLowerCase();
  return /entry/.test(type) && !/sequential|toggle/.test(type);
}
function renderPs462EntryTypeBadge(node){
  if(!isNewPowerSeries462Programming() || !isCompactProgrammingPresentation() || !node) return '';
  var typeText=getProgramTypeText(node);
  if(!isMeaningfulProgramValue(typeText)) return '';
  return '<span class="program-sequential-type">'+esc(String(typeText))+'</span>';
}

/* v686 — Standardized simple-entry sections for PowerSeries v4.62 New.
   Real 3-digit programming sections that are a single entry use the same
   expandable header/content language as sequential and toggle sections:
   an `entry` badge, compact table, then notes/references. Deep field-level
   children retain their established child-row presentation. */
function isPs462CompactEntrySection(node,depth){
  if(!isNewPowerSeries462Programming() || !isCompactProgrammingPresentation() || !node) return false;
  if(Array.isArray(node.children) && node.children.length) return false;
  /* v687: category grouping makes real 3-digit installer sections render at
     depth 2+ (for example [176]). Depth must not decide whether a section is
     an entry section. Identify it from the actual programming code/type. */
  if(!/^\d{3}$/.test(String(node.code||''))) return false;
  if(/(?:^|-)keypad-|(?:^|-)kp-/.test(String(node.id||''))) return false;
  return isPs462EntryTypedNode(node);
}
function ps462EntrySummaryColumns(node){
  return programmingCompactSummaryColumns(node).filter(function(column){
    return column && (column.cls==='digits' || column.cls==='default' || column.cls==='cp01');
  });
}
function renderPs462EntryTable(node){
  if(!node) return '';
  /* v721: standalone value displays use a dedicated table-like grid instead
     of <thead>/<tbody>.  This avoids generic/sticky table CSS ever collapsing
     the single value row while still preserving proper table semantics through
     ARIA roles.  Values are read directly from the programming record. */
  var digits='';
  if(isMeaningfulProgramValue(node.directEntryDigits)) digits=String(node.directEntryDigits);
  else{
    var maxChars=getProgramMaxCharsText(node);
    if(isMeaningfulProgramValue(maxChars)) digits=String(maxChars);
  }

  var std=getProgramDefaultText(node.defaultStd,node);
  if(!isMeaningfulProgramValue(std) && (isMeaningfulProgramValue(node.defaultValue) || isMeaningfulProgramValue(node.defaultLabel))){
    std=(node.defaultValue||'')+((node.defaultValue&&node.defaultLabel)?' - ':'')+(node.defaultLabel||'');
  }
  var cp01=getProgramDefaultText(node.defaultCp01,node);
  if(node.profileIndependent){
    var shared=std||cp01;
    std=shared;
    cp01=shared;
  }

  if(!isMeaningfulProgramValue(digits) && !isMeaningfulProgramValue(std) && !isMeaningfulProgramValue(cp01)) return '';

  var name=String(getProgrammingLabel(node)||node.label||node.code||'Entry');
  var values=[
    isMeaningfulProgramValue(digits)?digits:'—',
    name,
    isMeaningfulProgramValue(std)?std:'—',
    isMeaningfulProgramValue(cp01)?cp01:'—'
  ];
  var headers=['DIGITS','NAME','STND','CP01'];
  return '<div class="program-entry-table-wrap program-single-entry-grid-wrap">'+
    '<div class="program-single-entry-grid" role="table" aria-label="'+esc(name)+' values">'+
      '<div class="program-single-entry-grid-row program-single-entry-grid-head" role="row">'+
        headers.map(function(label){return '<div class="program-single-entry-grid-cell" role="columnheader">'+esc(label)+'</div>';}).join('')+
      '</div>'+ 
      '<div class="program-single-entry-grid-row program-single-entry-grid-values" role="row">'+
        values.map(function(value,index){return '<div class="program-single-entry-grid-cell program-single-entry-grid-value'+(index===3?' program-single-entry-grid-cp01':'')+'" role="cell">'+esc(value)+'</div>';}).join('')+
      '</div>'+ 
    '</div>'+ 
  '</div>';
}

function renderPs462EntrySection(node,depth){
  node.__depth=depth;
  if(node && node.id) renderedProgrammingNodeIndex[node.id]=node;
  var table=renderPs462EntryTable(node);
  var notes=renderPs462PlainNotes(node);
  var references=renderPs462InlineReferences(node);
  return '<div class="program-block program-zone-definition-sequence program-entry-section" id="'+esc(node.id||'')+'"'+(node.sourceNodeId?' data-source-node-id="'+esc(node.sourceNodeId)+'"':'')+rowIndent(depth)+'>'+ 
    '<button class="program-row program-toggle program-node-summary" type="button" data-program-toggle aria-expanded="false">'+
      guideMarkup(depth)+
      '<span class="program-caret"></span>'+ 
      renderProgrammingCode(node)+
      '<span class="program-main"><span class="program-title">'+esc(getProgrammingLabel(node))+'</span><span class="program-sequential-type">entry</span></span>'+ 
    '</button>'+ 
    '<div class="program-children program-zone-definition-sequence-body">'+
      '<div class="program-zone-definition-sequence-content program-entry-section-content">'+
        table+notes+references+
      '</div>'+ 
    '</div>'+ 
  '</div>';
}

function programmingCategoryToneClass(node){
  if(!node || !node.isCategory) return '';
  var label=String(getProgrammingLabel(node)||node.label||node.title||node.id||'').toLowerCase();
  if(label.indexOf('reporting')!==-1 || label.indexOf('event verification')!==-1) return ' program-category-tone-rose';
  if(label.indexOf('communication')!==-1) return ' program-category-tone-teal';
  if(label.indexOf('wireless')!==-1) return ' program-category-tone-sky';
  if(label.indexOf('international')!==-1 || label.indexOf('system times')!==-1 || label.indexOf('holiday')!==-1 || label.indexOf('schedule')!==-1 || label.indexOf('automation')!==-1) return ' program-category-tone-amber';
  if(label.indexOf('access code')!==-1 || label.indexOf('authentication')!==-1 || label.indexOf('dls ')!==-1 || label.indexOf('dls programming')!==-1 || label.indexOf('template')!==-1) return ' program-category-tone-violet';
  if(label.indexOf('pgm')!==-1) return ' program-category-tone-orange';
  if(label.indexOf('zone')!==-1 || label.indexOf('input programming')!==-1) return ' program-category-tone-green';
  if(label.indexOf('partition auto')!==-1) return ' program-category-tone-cyan';
  if(label.indexOf('partition')!==-1 || label.indexOf('system information')!==-1) return ' program-category-tone-blue';
  if(label.indexOf('system option')!==-1 || label.indexOf('system timing')!==-1) return ' program-category-tone-indigo';
  if(label.indexOf('module')!==-1 || label.indexOf('keypad')!==-1) return ' program-category-tone-cyan';
  if(label.indexOf('label')!==-1 || label.indexOf('text programming')!==-1) return ' program-category-tone-pink';
  if(label.indexOf('audio')!==-1 || label.indexOf('voice')!==-1 || label.indexOf('lockout')!==-1) return ' program-category-tone-rose';
  if(label.indexOf('test')!==-1 || label.indexOf('diagnostic')!==-1) return ' program-category-tone-teal';
  if(label.indexOf('default')!==-1 || label.indexOf('reset')!==-1 || label.indexOf('special')!==-1) return ' program-category-tone-pink';
  return ' program-category-tone-blue';
}
function renderProgrammingNode(node, depth){
  if(programmingHideUnused && isUnusedProgrammingItem(node)) return '';
  node.__depth=depth;
  if(node && node.id) renderedProgrammingNodeIndex[node.id]=node;
  if(isZoneDefinitionsTypeListSection(node)){
    return renderZoneDefinitionsTypeListSection(node, depth);
  }
  if(isPgmDefinitionsListSection(node)){
    return renderPgmDefinitionsListSection(node, depth);
  }
  if(isNeoLanguageSelectionOptionsListSection(node)){
    return renderNeoLanguageSelectionOptionsListSection(node, depth);
  }
  if(isPs462ZoneAttributeReferenceListSection(node)){
    return renderPs462ZoneAttributeReferenceListSection(node, depth);
  }
  if(isPs462CompactZoneDefinitionSequence(node)){
    return renderPs462ZoneDefinitionSequence(node, depth);
  }
  if(isPs462CompactSequentialSection(node)){
    return renderPs462SequentialSection(node, depth);
  }
  if(isPs462CompactToggleSection(node)){
    return renderPs462ToggleSection(node, depth);
  }
  if(isPs462CompactEntrySection(node,depth)){
    return renderPs462EntrySection(node, depth);
  }
  if(node && node.defaultZoneAttributesByTypeReference){
    return renderDefaultZoneAttributesByTypeSection(node, depth);
  }
  var directChildren=(node && Array.isArray(node.children)) ? filterUnusedProgrammingItems(node.children) : [];
  var hasResolvedLazyChildren=!!(node && node.lazyChildren && (node.relationshipTreeSpec || node.relationshipTreeNode || node.wirelessTemplateGroup || node.mirrorSectionId || (node.sectionRefs && node.sectionRefs.length)));
  var hasChildren=directChildren.length || hasResolvedLazyChildren;
  var rangeSummaryMatchesNode=!!(node.rangeSummary && String(node.code||'')===String(node.rangeSummary.code||'') && String(node.label||'')===String(node.rangeSummary.label||''));
  if(hasChildren && node.nonCollapsibleChildren){
    return renderProgrammingStaticParent(node, depth);
  }
  if(directChildren.length && node.rangeSummary && (node.renderAsFoldOnly || rangeSummaryMatchesNode)){
    return renderProgrammingFold(node, depth);
  }
  if(hasChildren){
    var childCount=hasResolvedLazyChildren ? getVisibleProgrammingChildren(node).length : directChildren.length;
    var childUnit=(node.isCategory || node.isRelationshipTopic) ? (childCount===1?'section':'sections') : 'lines';
    var blockClass='program-block'+(node.isCategory?' program-category':'')+programmingCategoryToneClass(node)+(node.isRelationshipTopic?' program-relationship-topic':'')+(node.relationshipReference?' program-relationship-reference':'');
    return '<div class="'+blockClass+'" id="'+esc(node.id||'')+'"'+(node.sourceNodeId?' data-source-node-id="'+esc(node.sourceNodeId)+'"':'')+rowIndent(depth)+'>'+ 
      '<button class="program-row program-toggle program-node-summary" type="button" data-program-toggle aria-expanded="false">'+ 
        guideMarkup(depth)+
        '<span class="program-caret"></span>'+ 
        renderProgrammingCode(node)+ 
        '<span class="program-main"><span class="program-title">'+esc(getProgrammingLabel(node))+'</span>'+renderPs462EntryTypeBadge(node)+renderProgrammingMeta(node)+'</span>'+ 
        '<em>'+childCount+' '+childUnit+'</em>'+ 
      '</button>'+ 
      renderProgrammingDetails(node)+ 
      renderProgrammingCompactSummary(node)+
      '<div class="program-children" data-lazy-program-children="'+esc(node.id||'')+'"></div>'+ 
    '</div>';
  }
  return renderProgrammingLeaf(node, depth);
}
// v712 — Toggle matrix sticky rows activate only after the matrix actually
// reaches its owning section header. Earlier CSS applied a large sticky top
// immediately, which displaced Toggle/Name rows and left blank space.
var compactToggleStickyRaf=0;
function refreshCompactToggleMatrixSticky(scope){
  var body=$('documentBody');
  if(!body || !isNewPowerSeries462Programming()) return;
  var root=scope && scope.querySelectorAll ? scope : body;
  var wraps=qsa('.program-toggle-section.is-open .program-toggle-matrix-group .program-toggle-table-wrap,.program-pgm-template-reference[open] .program-toggle-matrix-group .program-toggle-table-wrap',root);
  if(root!==body && root.matches && root.matches('.program-toggle-table-wrap')) wraps.unshift(root);
  wraps.forEach(function(wrap){
    if(!wrap || !wrap.getBoundingClientRect) return;
    var block=wrap.closest('.program-toggle-section');
    var ownerBlock=block || wrap.closest('.program-block');
    var header=ownerBlock ? compactProgrammingStickyHeader(ownerBlock) : null;
    if(!header){
      wrap.classList.remove('program-toggle-sticky-active');
      return;
    }
    var owner=programmingScrollOwner(wrap);
    var docRoot=document.scrollingElement || document.documentElement;
    var ownerTop=0;
    if(owner && owner!==docRoot){
      var ownerRect=owner.getBoundingClientRect();
      ownerTop=ownerRect.top+(owner.clientTop||0);
    }
    var headerRect=header.getBoundingClientRect();
    var wrapRect=wrap.getBoundingClientRect();
    var stickyViewportTop=Math.max(ownerTop,headerRect.bottom);
    var stickyLocalTop=Math.max(0,Math.ceil(stickyViewportTop-ownerTop));
    var thead=wrap.querySelector('thead');
    var nameRow=wrap.querySelector('tbody tr:first-child');
    var headHeight=thead ? Math.ceil(thead.getBoundingClientRect().height||34) : 34;
    var nameHeight=nameRow ? Math.ceil(nameRow.getBoundingClientRect().height||34) : 34;
    wrap.style.setProperty('--program-toggle-sticky-top',stickyLocalTop+'px');
    wrap.style.setProperty('--program-toggle-sticky-name-top',(stickyLocalTop+headHeight)+'px');
    var active=wrapRect.top<=stickyViewportTop && wrapRect.bottom>(stickyViewportTop+headHeight+nameHeight+4);
    wrap.classList.toggle('program-toggle-sticky-active',!!active);
  });
}
var compactToggleStickyScope=null;
function scheduleCompactToggleMatrixSticky(scope){
  compactToggleStickyScope=scope||$('documentBody');
  if(compactToggleStickyRaf) return;
  var run=function(){
    compactToggleStickyRaf=0;
    var target=compactToggleStickyScope||$('documentBody');
    compactToggleStickyScope=null;
    refreshCompactToggleMatrixSticky(target);
  };
  compactToggleStickyRaf=window.requestAnimationFrame ? window.requestAnimationFrame(run) : window.setTimeout(run,0);
}
/* v730 — Keep normal and PGM toggle matrices on the same sticky-row path.
   Listen only to the actual programming scroll host, not every nested scrollable
   table/reference element, and batch the geometry work to one animation frame. */
if(!window.__dscCompactToggleStickyBound){
  window.__dscCompactToggleStickyBound=true;
  document.addEventListener('scroll',function(event){
    var body=$('documentBody');
    if(!body || event.target!==body) return;
    scheduleCompactToggleMatrixSticky(body);
  },{capture:true,passive:true});
  window.addEventListener('resize',function(){scheduleCompactToggleMatrixSticky($('documentBody'));},{passive:true});
}

// Keep button state synchronized for clicks, search reveals, and bulk controls.
function compactProgrammingStickyHeader(block){
  if(!block) return null;
  try{
    return block.querySelector(':scope > [data-program-toggle]') ||
      block.querySelector(':scope > [data-program-compact-static-toggle]');
  }catch(err){
    return null;
  }
}
function compactProgrammingFoldControl(block){
  if(!block) return null;
  try{return block.querySelector(':scope > .program-fold-gutter-rail > [data-program-toggle]');}
  catch(err){
    var rail=block.querySelector('.program-fold-gutter-rail');
    return rail ? rail.querySelector('[data-program-toggle]') : null;
  }
}
/* v667: derive the sticky stack from DOM ancestry, not only from the is-open
   class. If a descendant is visible, every containing programming block is
   contextual, including non-collapsible/static parents. This prevents a child
   header from ever occupying the parent's sticky slot. */
function compactProgrammingStickyAncestors(element,root){
  var ancestors=[];
  if(!element) return ancestors;
  var parent=element.parentElement && element.parentElement.closest ? element.parentElement.closest('.program-block') : null;
  while(parent && (!root || root.contains(parent))){
    ancestors.unshift(parent);
    parent=parent.parentElement && parent.parentElement.closest ? parent.parentElement.closest('.program-block') : null;
  }
  return ancestors;
}
function compactProgrammingStickyTopFor(element,root){
  var top=-11;
  compactProgrammingStickyAncestors(element,root).forEach(function(ancestor){
    var ancestorHeader=compactProgrammingStickyHeader(ancestor);
    if(!ancestorHeader || ancestorHeader===element || ancestorHeader.contains(element)) return;
    var height=ancestorHeader.getBoundingClientRect().height || ancestorHeader.offsetHeight || 0;
    if(height>0) top+=height;
  });
  return Math.max(-11,Math.ceil(top));
}
function refreshCompactProgrammingStickyHeaders(scope){
  var body=$('documentBody');
  if(!body || body.getAttribute('data-programming-presentation')!=='compact-summary-table') return;
  var root=scope && scope.closest ? (scope.closest('#documentBody') || body) : body;
  qsa('.program-block > [data-program-toggle],.program-block > [data-program-compact-static-toggle],.program-fold > [data-program-toggle],.program-group-fold > .program-fold-gutter-rail',root).forEach(function(header){
    header.style.removeProperty('--program-compact-sticky-top');
    header.style.removeProperty('--program-compact-gutter-sticky-top');
  });
  qsa('.program-block',root).forEach(function(block){block.style.removeProperty('--program-inner-table-sticky-top');});
  qsa('.program-block.is-open:not(.program-category),.program-static-parent',root).forEach(function(block){
    var header=compactProgrammingStickyHeader(block);
    if(!header) return;
    var stickyTop=compactProgrammingStickyTopFor(block,root);
    header.style.setProperty('--program-compact-sticky-top',stickyTop+'px');
    var headerHeight=header.getBoundingClientRect().height || header.offsetHeight || 0;
    block.style.setProperty('--program-inner-table-sticky-top',Math.ceil(stickyTop+headerHeight)+'px');
  });
  qsa('.program-group-fold',root).forEach(function(fold){
    var rail=null;
    try{rail=fold.querySelector(':scope > .program-fold-gutter-rail');}
    catch(err){rail=fold.querySelector('.program-fold-gutter-rail');}
    if(!rail) return;
    rail.style.setProperty('--program-compact-gutter-sticky-top',(compactProgrammingStickyTopFor(fold,root)+7)+'px');
  });
  scheduleCompactToggleMatrixSticky(root);
}
var compactProgrammingStickyRaf=0;
var compactProgrammingStickyScope=null;
function scheduleCompactProgrammingStickyRefresh(scope){
  compactProgrammingStickyScope=scope||$('documentBody');
  if(compactProgrammingStickyRaf) return;
  var run=function(){
    compactProgrammingStickyRaf=0;
    var target=compactProgrammingStickyScope||$('documentBody');
    compactProgrammingStickyScope=null;
    refreshCompactProgrammingStickyHeaders(target);
  };
  compactProgrammingStickyRaf=window.requestAnimationFrame ? window.requestAnimationFrame(run) : window.setTimeout(run,0);
}
if(!window.__dscCompactProgrammingStickyResizeBound){
  window.__dscCompactProgrammingStickyResizeBound=true;
  window.addEventListener('resize',function(){scheduleCompactProgrammingStickyRefresh($('documentBody'));});
}
