  var category=header.parentElement;
  var categoryId=category ? category.id : '';
  var closing=category && (category.tagName==='DETAILS' ? category.open : category.classList.contains('is-open'));
  var headerSelector=header.tagName==='SUMMARY' ? ':scope > summary' : ':scope > [data-program-toggle]';
  var anchorTop=header.getBoundingClientRect().top;
  var originalScrollTop=owner.scrollTop;
  var anchorLeft=owner.scrollLeft;
  var reserveHost=programmingScrollReserveHost(header);
  var root=document.scrollingElement || document.documentElement;
  var spacerHost=owner===root ? document.body : owner;
  var runId=(owner.__categoryAnchorRun||0)+1;
  owner.__categoryAnchorRun=runId;
  if(owner.__categoryAnchorCleanup) owner.__categoryAnchorCleanup();
  var behaviorTarget=owner===root ? document.documentElement : owner;
  var oldBehavior=behaviorTarget.style.getPropertyValue('scroll-behavior');
  var oldBehaviorPriority=behaviorTarget.style.getPropertyPriority('scroll-behavior');
  var oldAnchor=owner.style.getPropertyValue('overflow-anchor');
  var oldAnchorPriority=owner.style.getPropertyPriority('overflow-anchor');
  behaviorTarget.style.setProperty('scroll-behavior','auto','important');
