    '.neo-specification-section','.neo-installation-section','.panel-model-specification-section','.comparison-card',
    '.knowledge-item','.family-card','.source-card','.snippet-card','.detail-block','.module-detail-hero',
    '.zone-type-item','[data-search-title]','[data-search-values]','details','tbody tr','article.card'
