function setupSidebarResizer(){
  var shell=document.querySelector('.shell');
  var handle=$('sidebarResizer');
  if(!shell || !handle) return;
  var storageKey='dsc-sidebar-width-v103';
  var defaultWidth=430;
  function limits(){
    var viewport=Math.max(document.documentElement.clientWidth||0,window.innerWidth||0);
    return {min:280,max:Math.max(280,Math.min(1000,viewport-360))};
  }
  function applyWidth(width,persist){
    var range=limits();
    var next=Math.max(range.min,Math.min(range.max,Math.round(Number(width)||defaultWidth)));
    shell.style.setProperty('--sidebar-width',next+'px');
    handle.setAttribute('aria-valuenow',String(next));
    if(persist){ try{localStorage.setItem(storageKey,String(next));}catch(err){} }
    return next;
  }
  var saved=defaultWidth;
  try{ saved=parseInt(localStorage.getItem(storageKey),10)||defaultWidth; }catch(err){}
  applyWidth(saved,false);
  var dragStartX=0,dragStartWidth=0,dragging=false;
  function stopDrag(pointerId){
    if(!dragging) return;
    dragging=false;
    document.body.classList.remove('is-resizing-sidebar');
    if(pointerId!==undefined && handle.hasPointerCapture && handle.hasPointerCapture(pointerId)) handle.releasePointerCapture(pointerId);
    var width=parseInt(getComputedStyle(shell).getPropertyValue('--sidebar-width'),10)||defaultWidth;
    applyWidth(width,true);
  }
  handle.addEventListener('pointerdown',function(event){
    if(event.button!==undefined && event.button!==0) return;
    dragging=true;
    dragStartX=event.clientX;
    dragStartWidth=document.querySelector('.sidebar').getBoundingClientRect().width;
    document.body.classList.add('is-resizing-sidebar');
    if(handle.setPointerCapture) handle.setPointerCapture(event.pointerId);
    event.preventDefault();
  });
  handle.addEventListener('pointermove',function(event){
    if(!dragging) return;
    applyWidth(dragStartWidth+(event.clientX-dragStartX),false);
  });
  handle.addEventListener('pointerup',function(event){stopDrag(event.pointerId);});
  handle.addEventListener('pointercancel',function(event){stopDrag(event.pointerId);});
  handle.addEventListener('dblclick',function(){applyWidth(defaultWidth,true);});
  handle.addEventListener('keydown',function(event){
    var current=parseInt(getComputedStyle(shell).getPropertyValue('--sidebar-width'),10)||defaultWidth;
    var step=event.shiftKey?50:10;
    if(event.key==='ArrowLeft'){event.preventDefault();applyWidth(current-step,true);}
    else if(event.key==='ArrowRight'){event.preventDefault();applyWidth(current+step,true);}
    else if(event.key==='Home'){event.preventDefault();applyWidth(limits().min,true);}
    else if(event.key==='End'){event.preventDefault();applyWidth(limits().max,true);}
  });
  window.addEventListener('resize',function(){
    var collapsed=shell.classList.contains('sidebar-collapsed');
    var inlineWidth=parseInt(shell.style.getPropertyValue('--sidebar-width'),10);
    var computedWidth=parseInt(getComputedStyle(shell).getPropertyValue('--sidebar-width'),10);
    var current=collapsed?(inlineWidth||saved||defaultWidth):(computedWidth||inlineWidth||saved||defaultWidth);
    applyWidth(current,false);
  });
}
function ensureImageLightbox(){
  var modal=document.querySelector('[data-image-lightbox-modal]');
  if(modal) return modal;
  var wrapper=document.createElement('div');
  wrapper.className='image-lightbox-modal';
  wrapper.setAttribute('data-image-lightbox-modal','');
  wrapper.setAttribute('hidden','');
  wrapper.setAttribute('role','dialog');
  wrapper.setAttribute('aria-modal','true');
  wrapper.setAttribute('aria-label','Image preview');
  wrapper.innerHTML='<button type="button" class="image-lightbox-backdrop" data-image-lightbox-close aria-label="Close image preview"></button><div class="image-lightbox-panel"><button type="button" class="image-lightbox-close" data-image-lightbox-close aria-label="Close image preview">×</button><img data-image-lightbox-img alt=""><div class="image-lightbox-copy"><strong data-image-lightbox-title></strong><span data-image-lightbox-caption></span></div></div>';
  document.body.appendChild(wrapper);
  return wrapper;
}
function openImageLightbox(src,title,caption){
  if(!src) return;
  var modal=ensureImageLightbox();
  var image=modal.querySelector('[data-image-lightbox-img]');
  var titleNode=modal.querySelector('[data-image-lightbox-title]');
  var captionNode=modal.querySelector('[data-image-lightbox-caption]');
  if(image){image.src=src;image.alt=title||'Image preview';}
  if(titleNode){titleNode.textContent=title||'';titleNode.hidden=!title;}
  if(captionNode){captionNode.textContent=caption||'';captionNode.hidden=!caption;}
  modal.removeAttribute('hidden');
  document.documentElement.classList.add('image-lightbox-open');
  var closeButton=modal.querySelector('.image-lightbox-close');
  if(closeButton) closeButton.focus({preventScroll:true});
}
function closeImageLightbox(){
  var modal=document.querySelector('[data-image-lightbox-modal]');
  if(!modal||modal.hasAttribute('hidden')) return;
  modal.setAttribute('hidden','');
  document.documentElement.classList.remove('image-lightbox-open');
  var image=modal.querySelector('[data-image-lightbox-img]');
  if(image) image.removeAttribute('src');
}
